//! Source-free generated output transaction. Per-file rename is atomic; the
//! collection is rollback-capable, NOT an atomic filesystem snapshot.
use crate::{GeneratorName,generation_journal::JournalPayload,input_snapshot::{FileSystemInputs,SnapshotProvider,Stamp},runner_host::query_snapshot::ClosedGeneration};
use std::{error::Error,fmt,fs::{self,File,OpenOptions},io::{self,Read,Write,Seek,SeekFrom,BufReader},path::{Path,PathBuf,Component},sync::atomic::{AtomicU64,Ordering}};
const LIMIT:usize=64*1024*1024;
static NEXT:AtomicU64=AtomicU64::new(1);
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub(crate) enum Mode{Check,Write}
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub(crate) enum State{Fresh,Written,Stale,NotIncluded}
#[derive(Debug)]pub(crate) struct OutputRow{pub name:GeneratorName,pub path:PathBuf,pub state:State}
#[derive(Debug)]pub(crate) struct Diagnostic{pub name:GeneratorName,pub relative:String,pub line:u32,pub message:String}
#[derive(Debug)]pub(crate) struct Report{pub rows:Vec<OutputRow>,pub diagnostics:Vec<Diagnostic>,pub changed:Vec<PathBuf>,pub cleanup:Vec<RollbackFailure>,pub committed:bool}
#[derive(Debug)]pub(crate) struct RollbackFailure{pub path:PathBuf,pub error:io::Error}
#[derive(Debug)]pub(crate) struct TransactionError{pub primary:Box<dyn Error>,pub rollback:Vec<RollbackFailure>}
impl fmt::Display for TransactionError{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{}",self.primary)?;for row in &self.rollback{write!(f,"; rollback failed for {}: {}",row.path.display(),row.error)?;}Ok(())}}
impl Error for TransactionError{fn source(&self)->Option<&(dyn Error+'static)>{Some(self.primary.as_ref())}}
impl From<io::Error> for TransactionError{fn from(primary:io::Error)->Self{Self{primary:Box::new(primary),rollback:Vec::new()}}}
fn invalid(s:impl Into<String>)->io::Error{io::Error::new(io::ErrorKind::InvalidData,s.into())}
struct Admission{used:std::cell::Cell<usize>}
impl Admission{fn charge(&self,n:usize)->io::Result<()>{let used=self.used.get().checked_add(n).filter(|n|*n<=LIMIT).ok_or_else(||io::Error::new(io::ErrorKind::OutOfMemory,"generation transaction metadata exceeds existing output bound"))?;self.used.set(used);Ok(())}fn row<T>(&self,v:&mut Vec<T>)->io::Result<()>{if v.len()<v.capacity(){return Ok(())}let cap=v.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||invalid("transaction row overflow"))?;self.charge(cap.checked_mul(4).and_then(|n|n.checked_mul(std::mem::size_of::<T>())).and_then(|n|n.checked_add(64)).ok_or_else(||invalid("transaction row overflow"))?)?;v.try_reserve_exact(cap-v.len()).map_err(|e|io::Error::new(io::ErrorKind::OutOfMemory,e))?;if v.capacity()>cap.saturating_mul(4){return Err(io::Error::new(io::ErrorKind::OutOfMemory,"transaction exposed capacity exceeds admission"))}Ok(())}fn path(&self,p:&Path)->io::Result<PathBuf>{self.charge(p.as_os_str().len().checked_mul(4).and_then(|n|n.checked_add(std::mem::size_of::<PathBuf>()+64)).ok_or_else(||invalid("transaction path overflow"))?)?;Ok(p.to_owned())}fn text(&self,s:&str)->io::Result<String>{self.charge(s.len().checked_add(64).ok_or_else(||invalid("transaction string overflow"))?)?;Ok(s.to_owned())}}
struct Previous{stamp:Stamp,offset:u64,length:u64}
struct Target{name:GeneratorName,relative:String,path:PathBuf,payload:JournalPayload,previous:Option<Previous>,fresh:bool,temporary:Option<OwnedTemp>,restore:Option<OwnedTemp>,attempted:Option<Stamp>}
struct CreatedDirectory{path:PathBuf,identity:Option<u128>}
struct OwnedTemp{path:PathBuf,stamp:Stamp,active:bool,complete:bool}
impl OwnedTemp{fn cleanup(&mut self)->io::Result<()>{if !self.active{return Ok(())}match FileSystemInputs.stamp(&self.path){Ok(current)if current.file_id.is_some()&&current.file_id==self.stamp.file_id&&(!self.complete||current==self.stamp)=>fs::remove_file(&self.path),Err(e)if e.kind()==io::ErrorKind::NotFound=>Ok(()),_=>Err(invalid("owned transaction temporary was replaced"))}}}
impl Drop for OwnedTemp{fn drop(&mut self){let _=self.cleanup();}}
#[derive(Clone,Copy,Debug)]pub(crate) enum Event{BeforeFinalFreshness,AfterReplacement(usize),AfterCommit,BeforeRollback(usize)}
fn linked(metadata:&fs::Metadata)->bool{if metadata.file_type().is_symlink(){return true}#[cfg(windows)]{use std::os::windows::fs::MetadataExt;return metadata.file_attributes()&0x400!=0}#[cfg(not(windows))]{false}}
fn ordinary_ancestors(root:&Path,path:&Path)->io::Result<PathBuf>{let relative=path.strip_prefix(root).map_err(|_|invalid("generated path escapes issued root"))?;if relative.components().any(|c|!matches!(c,Component::Normal(_))){return Err(invalid("generated path contains non-normal component"))}let root_meta=fs::symlink_metadata(root)?;if linked(&root_meta)||!root_meta.is_dir(){return Err(invalid("issued generation root is not an ordinary directory"))}let mut cursor=root.to_owned();let mut existing=cursor.clone();for part in relative.components(){cursor.push(part.as_os_str());match fs::symlink_metadata(&cursor){Ok(meta)=>{if linked(&meta)||!meta.is_dir(){return Err(invalid("generated ancestor is symlink/reparse/non-directory"))}existing=cursor.clone()},Err(e)if e.kind()==io::ErrorKind::NotFound=>break,Err(e)=>return Err(e)}}Ok(existing)}
fn target_stamp(root:&Path,path:&Path)->io::Result<Option<Stamp>>{ordinary_ancestors(root,path.parent().ok_or_else(||invalid("generated output has no parent"))?)?;match fs::symlink_metadata(path){Ok(meta)=>{if linked(&meta)||!meta.is_file(){return Err(invalid("generated target is symlink/reparse/non-file"))}FileSystemInputs.stamp(path).map(Some)},Err(e)if e.kind()==io::ErrorKind::NotFound=>Ok(None),Err(e)=>Err(e)}}
fn copy_range(file:&mut File,offset:u64,length:u64,out:&mut impl Write,poll:bool)->io::Result<()>{file.seek(SeekFrom::Start(offset))?;let mut source=Read::take(file,length);let mut bytes=[0u8;8192];while source.limit()!=0{if poll{crate::daemon::control::checkpoint()?}let n=source.read(&mut bytes)?;if n==0{return Err(io::ErrorKind::UnexpectedEof.into())}out.write_all(&bytes[..n])?;}Ok(())}
/// Byte-for-byte comparison after ONLY old CRLF normalization, as old gen::norm.
fn equals_current(current:&mut File,offset:u64,length:u64,desired:&mut dyn Read)->io::Result<bool>{current.seek(SeekFrom::Start(offset))?;let mut old=BufReader::with_capacity(8192,Read::take(current,length));let mut pending=None;let mut same=true;let mut desired_bytes=[0u8;8192];loop{let n=desired.read(&mut desired_bytes)?;if n==0{break}for &wanted in &desired_bytes[..n]{let next=normalized_byte(&mut old,&mut pending)?;if next!=Some(wanted){same=false}}}if normalized_byte(&mut old,&mut pending)?.is_some(){same=false}Ok(same)}
fn normalized_byte(reader:&mut impl Read,pending:&mut Option<u8>)->io::Result<Option<u8>>{let read=|reader:&mut dyn Read|->io::Result<Option<u8>>{let mut b=[0];Ok(match reader.read(&mut b)?{0=>None,_=>Some(b[0])})};let value=match pending.take(){Some(b)=>Some(b),None=>read(reader)?};if value==Some(b'\r'){let next=read(reader)?;if next==Some(b'\n'){return Ok(next)}*pending=next;}Ok(value)}
fn read_diagnostic(input:&mut dyn Read,length:u64,admit:&Admission)->io::Result<String>{let n=usize::try_from(length).map_err(|_|invalid("diagnostic length overflow"))?;admit.charge(n.checked_mul(4).and_then(|n|n.checked_add(64)).ok_or_else(||invalid("diagnostic capacity overflow"))?)?;let mut data=Vec::new();data.try_reserve_exact(n).map_err(|e|io::Error::new(io::ErrorKind::OutOfMemory,e))?;if data.capacity()>n.saturating_mul(4){return Err(invalid("diagnostic exposed excess capacity"))}input.read_to_end(&mut data)?;if data.len()!=n{return Err(invalid("diagnostic bytes differ from sealed length"))}String::from_utf8(data).map_err(|_|invalid("generation diagnostic is not UTF8"))}
fn prepared_temp(root:&Path,target:&Path,admit:&Admission,guards:&mut Vec<crate::frozen_inputs::GenerationAncestorGuard>,created:&mut Vec<CreatedDirectory>)->io::Result<(File,OwnedTemp)>{let parent=target.parent().ok_or_else(||invalid("generated output has no parent"))?;ordinary_ancestors(root,parent)?;let mut cursor=root.to_owned();for part in parent.strip_prefix(root).map_err(|_|invalid("generated parent outside root"))?.components(){cursor.push(part.as_os_str());match fs::symlink_metadata(&cursor){Ok(m)if !linked(&m)&&m.is_dir()=>(),Ok(_)=>return Err(invalid("generated parent changed kind")),Err(e)if e.kind()==io::ErrorKind::NotFound=>{admit.row(created)?;let owned=admit.path(&cursor)?;admit.charge(crate::frozen_inputs::generation_publication_guard_charge(cursor.parent().ok_or_else(||invalid("generated directory has no parent"))?,root)?)?;let mut owned=Some(owned);let identity=crate::frozen_inputs::create_guarded_directory_using(root,&cursor,&mut||Ok(()),&mut||{created.push(CreatedDirectory{path:owned.take().ok_or_else(||invalid("generated directory callback repeated"))?,identity:None});Ok(())})?;created.last_mut().unwrap().identity=Some(identity);},Err(e)=>return Err(e)}}admit.row(guards)?;guards.push(crate::frozen_inputs::generation_ancestor_guard(parent,root)?);for _ in 0..16{let sequence=NEXT.fetch_add(1,Ordering::Relaxed);admit.charge(parent.as_os_str().len().checked_mul(4).and_then(|n|n.checked_add(256)).ok_or_else(||invalid("temporary path overflow"))?)?;let path=parent.join(format!(".dmbd-generation-{}-{sequence}.tmp",std::process::id()));admit.row(created)?;match OpenOptions::new().write(true).create_new(true).open(&path){Ok(file)=>{let stamp=match crate::input_snapshot::stamp_handle(&file){Ok(stamp)=>stamp,Err(error)=>{drop(file);created.push(CreatedDirectory{path,identity:None});return Err(error)}};return Ok((file,OwnedTemp{path,stamp,active:true,complete:false}))},Err(e)if e.kind()==io::ErrorKind::AlreadyExists=>continue,Err(e)=>return Err(e)}}Err(io::Error::new(io::ErrorKind::AlreadyExists,"generation temporary namespace exhausted"))}
fn expected_target(root:&Path,target:&Target)->io::Result<()>{let expected=target.previous.as_ref().map(|p|&p.stamp);if target_stamp(root,&target.path)?.as_ref()!=expected{return Err(invalid("generated destination changed after transaction preflight"))}Ok(())}
fn rollback(root:&Path,targets:&mut[Target],backup:&mut File,admit:&Admission,guards:&mut Vec<crate::frozen_inputs::GenerationAncestorGuard>,created:&mut Vec<CreatedDirectory>,hook:&mut impl FnMut(Event)->io::Result<()>,mut failures:Vec<RollbackFailure>)->Vec<RollbackFailure>{for index in (0..targets.len()).rev(){let target=&mut targets[index];let Some(ours)=target.attempted.as_ref()else{continue};let pending=(||{hook(Event::BeforeRollback(index))?;let current=target_stamp(root,&target.path)?;if current.as_ref()!=Some(ours){if current.as_ref()==target.previous.as_ref().map(|p|&p.stamp){return Ok(())}return Err(invalid("rollback refuses externally replaced destination"))}if let Some(previous)=&target.previous{let mut temp=target.restore.take().ok_or_else(||invalid("prewritten rollback payload unavailable"))?;let _=previous;crate::publish::atomic_replace(&temp.path,&target.path)?;temp.active=false;}else{fs::remove_file(&target.path)?}Ok(())})();if let Err(error)=pending{failures.push(RollbackFailure{path:target.path.clone(),error});}}
 for target in targets{for mut temp in [target.temporary.take(),target.restore.take()].into_iter().flatten(){if let Err(error)=temp.cleanup(){failures.push(RollbackFailure{path:temp.path.clone(),error})}}}guards.clear();for directory in created.iter().rev(){let removal=(||{let identity=directory.identity.ok_or_else(||invalid("created transaction entry identity unavailable; cleanup refuses uncertain entry"))?;if crate::frozen_inputs::generation_directory_identity(&directory.path,root)?!=identity{return Err(invalid("rollback refuses externally replaced directory"))}fs::remove_dir(&directory.path)})();if let Err(error)=removal{if error.kind()!=io::ErrorKind::NotFound{failures.push(RollbackFailure{path:directory.path.clone(),error})}}}failures}
/// No snapshot/source guard or cached Budget reaches this entry. State is
/// returned only after successful installation; failures retain rollback detail.
pub(crate) fn commit(closed:ClosedGeneration,cache_root:&Path,mode:Mode)->Result<Report,TransactionError>{commit_using(closed,cache_root,mode,&mut|_|Ok(()))}
pub(crate) fn commit_using(closed:ClosedGeneration,cache_root:&Path,mode:Mode,hook:&mut impl FnMut(Event)->io::Result<()>)->Result<Report,TransactionError>{commit_using_existing(closed,cache_root,mode,hook,0)}
pub(crate) fn commit_with_existing(closed:ClosedGeneration,cache_root:&Path,mode:Mode,existing:usize)->Result<Report,TransactionError>{commit_using_existing(closed,cache_root,mode,&mut|_|Ok(()),existing)}
fn commit_using_existing(closed:ClosedGeneration,cache_root:&Path,mode:Mode,hook:&mut impl FnMut(Event)->io::Result<()>,existing:usize)->Result<Report,TransactionError>{commit_retaining_check(closed,cache_root,mode,hook,existing,None).map(|(report,_)|report)}
pub(crate) fn capture_check(closed:ClosedGeneration,cache_root:&Path,existing:usize,work:&dyn dm_preprocess::source_arena_credit::SourceArenaWork)->Result<(Report,CheckEvidence),TransactionError>{let(report,evidence)=commit_retaining_check(closed,cache_root,Mode::Check,&mut|_|Ok(()),existing,Some(work))?;Ok((report,evidence.ok_or_else(||invalid("actual Check evidence was not retained"))?))}
fn commit_retaining_check(mut closed:ClosedGeneration,cache_root:&Path,mode:Mode,hook:&mut impl FnMut(Event)->io::Result<()>,existing:usize,observe:Option<&dyn dm_preprocess::source_arena_credit::SourceArenaWork>)->Result<(Report,Option<CheckEvidence>),TransactionError>{
 if observe.is_some()&&mode!=Mode::Check{return Err(invalid("generation observation is CHECK-only").into())}

 let admit=Admission{used:std::cell::Cell::new(8192)};admit.charge(existing)?;let root=admit.path(closed.inputs.root())?;let actual_root=fs::canonicalize(&root)?;let actual_cache=fs::canonicalize(cache_root)?;if actual_cache.starts_with(&actual_root){return Err(invalid("generation scratch must be outside issued source root").into())}
 let _lease=crate::publish::generation_destination_lease()?;let mut guards=Vec::new();admit.row(&mut guards)?;guards.push(crate::frozen_inputs::generation_ancestor_guard(&root,&root)?);closed.inputs.require_current(&FileSystemInputs).map_err(|primary|TransactionError{primary,rollback:Vec::new()})?;
 let mut backup=crate::generation_staging::temporary_output(cache_root)?;let mut backup_length=0u64;let mut targets=Vec::<Target>::new();let mut diagnostics=Vec::<Diagnostic>::new();let names:Vec<_>=closed.inputs.names().collect();let mut current=None;let mut ordinal=0usize;let mut per_name=[0usize;13];let mut diagnostics_started=false;
 // Journal path scratch and retained plan share this same source-free counter.
 closed.journal.visit_indexed(&mut|n|admit.charge(n),&mut|kind,line,path,length,body,payload|{
  crate::daemon::control::checkpoint()?;match kind{
   3=>{let name=*names.get(ordinal).ok_or_else(||invalid("unrequested generator boundary"))?;if line as usize!=ordinal||path!=name.name(){return Err(invalid("generator boundary/order differs from issued closure"))}current=Some(name);ordinal+=1;diagnostics_started=false;},
   1=>{let name=current.ok_or_else(||invalid("file precedes generator boundary"))?;if diagnostics_started{return Err(invalid("file follows generator diagnostic phase"))}crate::query_db::QueryDb::validate_generation_output(&root,name,path).map_err(invalid)?;admit.charge(root.as_os_str().len().checked_add(path.len()).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(128)).ok_or_else(||invalid("destination path overflow"))?)?;let target=root.join(path);for old in &targets{if crate::publish::generation_paths_alias(&old.path,&target)?{return Err(invalid("duplicate or aliased generated destination"))}}
    let previous=match target_stamp(&root,&target)?{None=>None,Some(stamp)=>{let mut file=File::open(&target)?;if crate::input_snapshot::stamp_handle(&file)?!=stamp{return Err(invalid("generated destination changed before backup"))}let end=backup_length.checked_add(stamp.size).filter(|n|*n<=LIMIT as u64).ok_or_else(||io::Error::new(io::ErrorKind::OutOfMemory,"generation rollback backup exceeds existing output bound"))?;backup.seek(SeekFrom::Start(backup_length))?;let mut limited=Read::take(&mut file,stamp.size);let copied=io::copy(&mut limited,&mut backup)?;drop(limited);let mut excess=[0u8;1];if file.read(&mut excess)?!=0{return Err(invalid("generated destination grew during backup"))}if copied!=stamp.size||crate::input_snapshot::stamp_handle(&file)?!=stamp||FileSystemInputs.stamp(&target)?!=stamp{return Err(invalid("generated destination changed during backup"))}let value=Previous{stamp,offset:backup_length,length:copied};backup_length=end;Some(value)}};
    let fresh=if let Some(previous)=&previous{equals_current(&mut backup,previous.offset,previous.length,body)?}else{io::copy(body,&mut io::sink())?;false};admit.row(&mut targets)?;targets.push(Target{name,relative:admit.text(path)?,path:target,payload,previous,fresh,temporary:None,restore:None,attempted:None});per_name[ordinal-1]+=1;
   },
   2=>{let name=current.ok_or_else(||invalid("diagnostic precedes generator boundary"))?;diagnostics_started=true;let message=read_diagnostic(body,length,&admit)?;admit.row(&mut diagnostics)?;diagnostics.push(Diagnostic{name,relative:admit.text(path)?,line,message});},
   _=>return Err(invalid("invalid generation journal record")),
  }Ok(())
 })?;if ordinal!=names.len(){return Err(invalid("missing requested generator boundary").into())}for(index,name)in names.iter().enumerate(){if *name!=GeneratorName::UiTypes&&per_name[index]!=1{return Err(invalid("registered single-output generator omitted or duplicated its file").into())}}
 admit.charge(targets.len().checked_mul(2*std::mem::size_of::<Target>()).and_then(|n|n.checked_add(diagnostics.len().checked_mul(2*std::mem::size_of::<Diagnostic>())?)).and_then(|n|n.checked_add(128)).ok_or_else(||invalid("generation ordered row scratch overflow"))?)?;targets.sort_by(|a,b|a.name.name().cmp(b.name.name()));diagnostics.sort_by(|a,b|a.name.name().cmp(b.name.name()));
 let included=closed.included();let mut report=Report{rows:Vec::new(),diagnostics,changed:Vec::new(),cleanup:Vec::new(),committed:false};for target in &targets{let mut state=if target.fresh{State::Fresh}else if mode==Mode::Check{State::Stale}else{State::Written};if state==State::Written{admit.row(&mut report.changed)?;report.changed.push(admit.path(&target.path)?);}if state!=State::Stale&&!included[names.iter().position(|name|*name==target.name).unwrap()]{state=State::NotIncluded;}admit.row(&mut report.rows)?;report.rows.push(OutputRow{name:target.name,path:admit.path(&target.path)?,state});}
 // A diagnostic-only UiTypes phase has no physical output row. The sealed
 // boundary/diagnostic records and current input closure above still prove
 // its actual producer completion; UI_NO_FILE belongs only to text display.
 let mut created=Vec::new();hook(Event::BeforeFinalFreshness)?;closed.inputs.require_current(&FileSystemInputs).map_err(|primary|TransactionError{primary,rollback:Vec::new()})?;crate::daemon::control::checkpoint()?;
 let mut rollback_failures=Vec::new();
 let install=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||->io::Result<()>{if mode==Mode::Write{
 // Materialize all desired and rollback files before replacing a destination.
 // Rollback needs no allocation or source read to restore previous bytes.
 for target in targets.iter_mut().filter(|t|!t.fresh){expected_target(&root,target)?;let(mut file,temp)=prepared_temp(&root,&target.path,&admit,&mut guards,&mut created)?;target.temporary=Some(temp);closed.journal.copy_payload(target.payload,&mut file)?;let temp=target.temporary.as_mut().unwrap();temp.stamp=crate::publish::generation_finish_owned(file,&temp.path)?;temp.complete=true;if let Some(previous)=&target.previous{let(mut file,temp)=prepared_temp(&root,&target.path,&admit,&mut guards,&mut created)?;target.restore=Some(temp);copy_range(&mut backup,previous.offset,previous.length,&mut file,true)?;let temp=target.restore.as_mut().unwrap();temp.stamp=crate::publish::generation_finish_owned(file,&temp.path)?;temp.complete=true;}}
 let failure_capacity=targets.len().checked_mul(3).and_then(|n|n.checked_add(created.len())).ok_or_else(||invalid("rollback error capacity overflow"))?;admit.charge(failure_capacity.checked_mul(4*std::mem::size_of::<RollbackFailure>()).and_then(|n|n.checked_add(64)).ok_or_else(||invalid("rollback error byte overflow"))?)?;rollback_failures.try_reserve_exact(failure_capacity).map_err(|e|io::Error::new(io::ErrorKind::OutOfMemory,e))?;if rollback_failures.capacity()>failure_capacity.saturating_mul(4){return Err(io::ErrorKind::OutOfMemory.into())}for target in &targets{admit.charge(target.path.as_os_str().len().checked_mul(12).and_then(|n|n.checked_add(192)).ok_or_else(||invalid("rollback path overflow"))?)?;}for directory in &created{admit.charge(directory.path.as_os_str().len().checked_mul(4).and_then(|n|n.checked_add(64)).ok_or_else(||invalid("rollback directory path overflow"))?)?;}
 // Acquire all anchored publication guards BEFORE releasing any strict guard.
 // Their no-delete child anchors prevent a reparse transition; WRITE sharing
 // permits the existing atomic_replace to rename children under these parents.
 let mut publication=Vec::new();for target in targets.iter().filter(|target|!target.fresh){admit.row(&mut publication)?;let parent=target.path.parent().ok_or_else(||invalid("generated publication parent absent"))?;publication.push(admitted_publication_guard(&admit,parent,&root)?);}
 if !publication.is_empty(){guards=publication;}
 for(index,target)in targets.iter_mut().enumerate(){if target.fresh{continue}crate::daemon::control::checkpoint()?;expected_target(&root,target)?;let temp=target.temporary.as_ref().unwrap();target.attempted=Some(temp.stamp.clone());crate::publish::atomic_replace(&temp.path,&target.path)?;target.temporary.as_mut().unwrap().active=false;hook(Event::AfterReplacement(index))?;}}Ok(())}));
 let install=match install{Ok(result)=>result,Err(_)=>Err(io::Error::other("generation installation panicked; rollback attempted"))};
 if let Err(primary)=install{let rollback=rollback(&root,&mut targets,&mut backup,&admit,&mut guards,&mut created,hook,rollback_failures);return Err(TransactionError{primary:Box::new(primary),rollback})}
 // Every replacement succeeded: cleanup errors are committed warnings, never
 // an unsafe rollback after another backup has already been removed.
 if let Err(error)=hook(Event::AfterCommit){rollback_failures.push(RollbackFailure{path:root.clone(),error});}
 for target in &mut targets{for mut temp in [target.temporary.take(),target.restore.take()].into_iter().flatten(){if let Err(error)=temp.cleanup(){rollback_failures.push(RollbackFailure{path:temp.path.clone(),error});}}}
 report.cleanup=rollback_failures;report.committed=mode==Mode::Write&&targets.iter().any(|target|!target.fresh);
 let evidence=if let Some(work)=observe{
  work.checkpoint()?;let owned=admit.used.get().checked_sub(existing).and_then(|n|n.checked_add(std::mem::size_of::<CheckEvidence>())).ok_or_else(||io::Error::from(io::ErrorKind::OutOfMemory))?;let bytes=owned.checked_add(closed.inputs.observation_retention_charge()?).ok_or_else(||io::Error::from(io::ErrorKind::OutOfMemory))?;let credit=work.reserve(bytes)?;
  let mut evidence=CheckEvidence{closed,targets,backup,bytes,_credit:credit};evidence.require_current().map_err(|primary|TransactionError{primary,rollback:Vec::new()})?;Some(evidence)
 }else{None};Ok((report,evidence))
}

#[cfg(test)]mod transaction_path_tests{use super::*;#[test]fn generation_transaction_rejects_real_symlink_ancestor_without_touching_external_directory(){let root=crate::test_scratch::dir("generation-transaction-symlink-root");let external=crate::test_scratch::dir("generation-transaction-symlink-external");fs::create_dir(root.join("code")).unwrap();fs::write(external.join("untouched"),b"external").unwrap();#[cfg(windows)]std::os::windows::fs::symlink_dir(&external,root.join("code/engine")).expect("actual symlink privilege is required for this filesystem negative");#[cfg(unix)]std::os::unix::fs::symlink(&external,root.join("code/engine")).unwrap();#[cfg(any(windows,unix))]{assert!(ordinary_ancestors(&root,&root.join("code/engine/_generated")).is_err());assert_eq!(fs::read(external.join("untouched")).unwrap(),b"external");}}}

fn admitted_publication_guard(admit:&Admission,parent:&Path,root:&Path)->io::Result<crate::frozen_inputs::GenerationAncestorGuard>{
 admit.charge(crate::frozen_inputs::generation_publication_guard_charge(parent,root)?)?;
 crate::frozen_inputs::generation_publication_guard(parent,root)
}
#[cfg(all(test,windows))]
mod publication_admission_tests{use super::*;
 #[test]fn actual_deep_publication_guard_backing_is_funded_before_anchor_creation(){
  let root=crate::test_scratch::dir("generation-publication-deep");let mut parent=root.clone();for _ in 0..20{parent.push("x")}fs::create_dir_all(&parent).unwrap();let charge=crate::frozen_inputs::generation_publication_guard_charge(&parent,&root).unwrap();assert!(charge>parent.as_os_str().len()*16+4096,"actual ancestor storage cannot use only terminal path width");
  let deny=Admission{used:std::cell::Cell::new(LIMIT-1)};assert_eq!(admitted_publication_guard(&deny,&parent,&root).err().unwrap().kind(),io::ErrorKind::OutOfMemory);assert_eq!(fs::read_dir(&parent).unwrap().count(),0,"quota refuses before the real publication anchor is created");
  let healthy=Admission{used:std::cell::Cell::new(0)};let guard=admitted_publication_guard(&healthy,&parent,&root).unwrap();assert_eq!(healthy.used.get(),charge);assert_eq!(fs::read_dir(&parent).unwrap().count(),1);drop(guard);assert_eq!(fs::read_dir(&parent).unwrap().count(),0);
 }
}

/// Real closed phase/source and target owners, retained only by CHECK capture.
pub(crate) struct CheckEvidence{
 closed:ClosedGeneration,targets:Vec<Target>,backup:File,bytes:usize,
 _credit:dm_preprocess::source_arena_credit::SourceArenaCredit,
}
impl CheckEvidence{
 pub(crate) fn retained_bytes(&self)->usize{self.bytes}
 pub(crate) fn names(&self)->impl Iterator<Item=GeneratorName>+'_ {self.closed.inputs.names()}
 pub(crate) fn journal_identity(&self)->(u64,u64,u128){self.closed.journal.observation_identity()}
 pub(crate) fn retained_spool_bytes(&self)->io::Result<u64>{self.closed.journal.observation_identity().0.checked_add(self.backup.metadata()?.len()).ok_or(io::ErrorKind::OutOfMemory.into())}

 pub(crate) fn root(&self)->&Path{self.closed.inputs.root()}
 pub(crate) fn matches_names(&self,names:&[GeneratorName])->bool{self.closed.inputs.names().eq(names.iter().copied())}
 pub(crate) fn require_current(&mut self)->Result<(),Box<dyn Error>>{
  crate::daemon::control::checkpoint()?;self.closed.inputs.require_current_exact()?;
  for target in &self.targets{
   crate::daemon::control::checkpoint()?;expected_target(self.closed.inputs.root(),target)?;
   if let Some(previous)=&target.previous{
    let mut actual=File::open(&target.path)?;if crate::input_snapshot::stamp_handle(&actual)?!=previous.stamp{return Err(invalid("observed generated destination changed before exact check").into())}
    self.backup.seek(SeekFrom::Start(previous.offset))?;let mut left=previous.length;let(mut want,mut got)=([0u8;8192],[0u8;8192]);while left!=0{crate::daemon::control::checkpoint()?;let count=left.min(want.len()as u64)as usize;self.backup.read_exact(&mut want[..count])?;actual.read_exact(&mut got[..count])?;if want[..count]!=got[..count]{return Err(invalid("observed generated destination bytes changed").into())}left-=count as u64;}
    let mut tail=[0u8;1];if actual.read(&mut tail)?!=0||crate::input_snapshot::stamp_handle(&actual)?!=previous.stamp{return Err(invalid("observed generated destination changed during exact check").into())}expected_target(self.closed.inputs.root(),target)?;
   }
  }
  self.closed.journal.verify_for_observation()?;crate::daemon::control::checkpoint()?;Ok(())
 }
 pub(crate) fn write_inputs(&self,output:&mut impl Write)->io::Result<()>{self.closed.inputs.write_observed_inputs(output)}
 pub(crate) fn write_journal(&mut self,output:&mut impl Write)->io::Result<()>{self.closed.journal.write_observed_journal(output)}
 pub(crate) fn write_targets(&mut self,output:&mut impl Write)->io::Result<()>{
  use serde::{Serialize,Serializer as _};use serde::ser::SerializeSeq;#[derive(Serialize)]struct Row<'a>{generator:&'static str,path:&'a Path,previous:Option<&'a Stamp>,previous_hash:Option<dq_analyze::selected_exclusions_wire::Hex128>,previous_length:Option<u64>,desired_extent:(u64,u64)}
  let mut serializer=serde_json::Serializer::new(output);let mut rows=serializer.serialize_seq(Some(self.targets.len())).map_err(io::Error::from)?;
  for target in &self.targets{crate::daemon::control::checkpoint()?;let hash=if let Some(previous)=&target.previous{let mut hash=xxhash_rust::xxh3::Xxh3::new();struct Hash<'a>(&'a mut xxhash_rust::xxh3::Xxh3);impl Write for Hash<'_>{fn write(&mut self,bytes:&[u8])->io::Result<usize>{self.0.update(bytes);Ok(bytes.len())}fn flush(&mut self)->io::Result<()>{Ok(())}}copy_range(&mut self.backup,previous.offset,previous.length,&mut Hash(&mut hash),true)?;Some(dq_analyze::selected_exclusions_wire::Hex128(hash.digest128()))}else{None};
   rows.serialize_element(&Row{generator:target.name.name(),path:&target.path,previous:target.previous.as_ref().map(|p|&p.stamp),previous_hash:hash,previous_length:target.previous.as_ref().map(|p|p.length),desired_extent:target.payload.observation_extent()}).map_err(io::Error::from)?;
  }rows.end().map_err(io::Error::from)
 }
}
